(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const date=v=>v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'';
  const preview=()=>window.ColorWinAuth.session?.user?.id==='preview';
  const user=()=>window.ColorWinAuth.session?.user?.id||'';
  const icon=n=>`<img src="assets/icons/${['user','key','email','check'].includes(n)?'payout/':''}${n}.svg" alt="" aria-hidden="true">`;
  const routes={Transaction:'#/account/transactions',VIP:'#/vip',Customer:'#/support',Notification:'#/account/notifications',Announcement:'#/account/notifications/information',Gifts:'#/account/gifts','My Top-Up Coupons':'#/account/coupons','Game Statistics':'#/account/statistics',Language:'#/account/language',Feedback:'#/account/feedback',Guide:'#/account/guide','About us':'#/account/about',Settings:'#/account/settings'};
  let owner='',data={balance:0,gifts:[],notifications:[],games:[]},loading=null;
  const resetOwner=()=>{if(owner!==user()){owner=user();data={balance:0,gifts:[],notifications:[],games:[]};loading=null;}};
  async function load(){resetOwner();if(preview())return data;if(!loading){const requested=user();loading=window.ColorWinAuth.accountRpc('colorwin_account_data').then(d=>{if(user()===requested)data=d;return d;}).finally(()=>{loading=null;});}return loading;}
  function balance(){resetOwner();return Number(data.balance||0);}
  function nickname(){return preview()?localStorage.getItem('cw_preview_nickname')||'Member123456':window.ColorWinAuth.profile?.display_name||'Member';}
  const header=(title,back='#/account')=>`<header class="ac-header"><a href="${back}" aria-label="Go back">‹</a><h1>${esc(title)}</h1><span></span></header>`;
  const empty=()=>'<div class="ac-empty agency-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><p>No data</p></div>';
  const tabs=(items)=>`<div class="ac-tabs" role="tablist">${items.map(([key,label],i)=>`<button type="button" role="tab" aria-selected="${i===0}" data-ac-tab="${key}">${label}</button>`).join('')}</div>`;
  const eye=(visible=false)=>`<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/>${visible?'<path d="m3 3 18 18"/>':''}</svg>`;
  const field=(name,label,type='text',placeholder=label,extra='')=>`<label class="ac-field"><span>${icon(type==='password'?'key':type==='email'?'email':'user')}${label}</span><div class="ac-input"><input name="${name}" type="${type}" placeholder="${esc(placeholder)}" required ${extra}>${type==='password'?`<button type="button" class="ac-eye" data-ac-eye="${name}" aria-pressed="false" aria-label="Show ${label.toLowerCase()}">${eye()}</button>`:''}</div></label>`;
  const primary=(text)=>`<button class="ac-primary" type="submit">${text}</button>`;
  const banner=(kind,title,subtitle)=>`<section class="ac-banner ac-banner-${kind}"><div><strong>${title}</strong><span>${subtitle}</span></div><img src="assets/account/${kind==='gift'?'gift-premium.png':kind+'.svg'}" alt="${kind==='gift'?'Premium crown, gift box and redemption coupon':''}"></section>`;
  const row=(href,label,asset,value='')=>`<a class="ac-row" href="${href}">${icon(asset)}<span>${label}</span><small>${esc(value)}</small><b>›</b></a>`;
  const notices=[['Important Security Notice','Protect your account. Keep your password and verification codes private. Use the support options inside Color Win to check any unusual account activity.'],['Welcome to Color Win','Welcome to Color Win. Explore the games, account controls and help pages. Your account notifications and transaction updates will appear in the Notification tab.']];
  const guide=[
    ['Create an account',['Open Register from the login page.','Enter your phone number and choose a strong password.','Confirm the password, review the account terms and complete registration.','Keep your password and verification codes private.'],['#/register','Open registration']],
    ['Log in',['Choose phone or email login.','Enter your registered account details and password.','Use the recovery option if you cannot remember your password.','Check the last login time on your Account page.'],['#/login','Open login']],
    ['Find a game',['Go to Home and select a category.','Open a game to read its rules before playing.','Check the amount and selection before confirming any action.','Use Game Statistics to review available play records.'],['#/home','Explore Home']],
    ['Deposit',['Open Deposit from Account.','Choose your payment method and enter an amount.','Use the order’s QR or payment details for the exact amount.','Submit the transfer reference if requested and check Deposit history.','A transfer needs verification before it is confirmed.'],['#/deposit','Open Deposit']],
    ['Withdraw',['Open Withdraw and choose UPI, bank card or USDT.','Add your payout details and check them before saving.','For USDT, match the beneficiary network to the transfer network.','Enter an amount within your withdrawable balance.','For the displayed conversion, 1 USDT equals ₹104.','Check Withdrawal history for the request status.'],['#/withdraw','Open Withdraw']],
    ['Transaction records',['Open Deposit history or Withdrawal history from Account.','Review the amount, time, method and order status.','Copy the order number when you need help with a transaction.','Keep your transfer reference until verification is complete.'],['#/deposit/history','View Deposit history']],
    ['Promotion',['Open Promotion from the navigation bar.','View your invitation code and the displayed promotion terms.','Check direct and team activity in the Promotion section.','Rewards depend on the published offer conditions.'],['#/promotion','Open Promotion']],
    ['Change your login password',['Open Settings Center, then Login password.','Enter your current password and a new password.','Confirm the new password and save the change.','Use a unique password with at least eight characters.'],['#/account/settings/password','Change password']],
    ['Gifts and coupons',['Open Gifts and enter a code supplied by an administrator.','A valid code can be claimed once per account.','Cash gifts appear in your wallet balance after confirmation.','Coupon gifts appear in My Top-Up Coupons.','Check the deposit threshold and expiry before using a coupon.'],['#/account/gifts','Open Gifts']],
    ['Support and account care',['Check Information for account notices.','Send a clear description through Feedback when something goes wrong.','Never include passwords or verification codes in feedback.','Use Settings to update your nickname, avatar and verified email.'],['#/account/feedback','Send Feedback']]
  ];
  const documents={confidentiality:['Your account details should be kept private.','Use a unique password for your Color Win account.','Do not share login credentials with another person.','Verification codes are intended only for the account owner.','Account records help you review your own activity.','Provide only the information needed for account features.','Use the in-app support channels for account questions.','Review recipient details before sharing transaction references.','Sign out when you use a shared device.','Check the Information tab for published account notices.'],risk:['Review the rules of a game before taking part.','Game outcomes are uncertain and returns are not guaranteed.','Choose a spending limit you can comfortably afford.','Avoid using funds needed for daily living expenses.','Take regular breaks and keep track of your activity.','A previous result does not guarantee a future result.','Review amounts carefully before confirming a transaction.','Check payout details and the selected transfer network.','Payment and withdrawal processing depend on verification.','If play becomes difficult to control, stop and seek support.']};
  function settings(){const a=localStorage.getItem('cw_avatar_'+user())||localStorage.getItem('cw_avatar')||'avatar-1.jpg';return `<div class="ac-settings-cover"></div><section class="ac-card ac-settings-profile"><button type="button" class="ac-avatar-row" id="ac-avatar"><img src="assets/avatars/${esc(window.ColorWinAccount.avatar?.()||a)}" alt="Your avatar"><span>Change avatar</span><b>›</b></button>${row('#/account/settings/nickname','Nickname','user',nickname())}<button type="button" class="ac-row" id="ac-copy"><span>UID</span><small>${esc(window.ColorWinAuth.profile?.public_uid||'—')}</small><b>⧉</b></button></section><h2 class="ac-section-title">Security information</h2><div class="ac-security">${row('#/account/settings/password','Login password','key','Edit')}${row('#/account/settings/email','Bind mailbox','email',window.ColorWinAuth.session?.user?.email?.endsWith('@auth.colorwin.invalid')?'to bind':'Edit')}<button type="button" class="ac-row" id="ac-version">${icon('about-us')}<span>Updated version</span><small>1.0.0</small><b>›</b></button></div>`;}
  function view(route){resetOwner();const part=route.split('/')[2],sub=route.split('/')[3];let title='',body='',back='#/account';
    if(part==='transactions')return window.ColorWinTransactions.view();
    if(part==='notifications'){title='Notification';body=tabs([['notification','Notification'],['information','Information']])+'<div id="ac-list"></div>';}
    if(part==='gifts'){title='Gifts';body=banner('gift','Hi','We have a gift for you')+`<form class="ac-card ac-gift-form" id="ac-gift"><h2>Please enter the gift code below</h2><input name="code" aria-label="Gift code" placeholder="Please enter gift code" maxlength="32" autocomplete="off" required>${primary('Receive')}</form><section class="ac-card"><h2>${icon('deposit-history')}History</h2><div id="ac-list"></div></section><section class="ac-card"><h2>${icon('about-us')}Redemption Notes</h2><ul class="ac-notes"><li>One code claims one gift. Cash is credited to your wallet; coupons go to My Top-Up Coupons.</li><li>Coupons have a deposit threshold and expiry. Use them before they expire.</li></ul></section>`;}
    if(part==='coupons'){title='My Top-Up Coupons';body=tabs([['unused','Unused'],['used','Used'],['expired','Expired']])+'<div id="ac-list"></div>';}
    if(part==='statistics'){title='Game statistics';body=tabs([['today','Today'],['yesterday','Yesterday'],['week','This week'],['month','This month']])+'<div id="ac-stats"></div>';}
    if(part==='language'){title='Language';body='<button type="button" class="ac-language" aria-pressed="true"><span>🇺🇸</span> English <b>✓</b></button>';}
    if(part==='feedback'){title='Feedback';body=`<form id="ac-feedback"><textarea name="message" aria-label="Feedback" minlength="10" maxlength="2000" required placeholder="Welcome to feedback. Please describe the problem in detail so our team can review it."></textarea><p class="ac-feedback-copy">Send helpful feedback<br>Help us improve Color Win</p><img class="ac-feedback-art" src="assets/account/feedback.png" alt="Color Win feedback assistant">${primary('Submit')}</form>`;}
    if(part==='guide'){title='Beginner’s Guide';body=`<div class="ac-guide-intro"><strong>Getting started with Color Win</strong><p>Your step-by-step guide to your account, payments and help.</p></div>${guide.map(([t,steps,link],i)=>`<section class="ac-card ac-guide-step"><h2><b>${i+1}</b>${t}</h2><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol><a href="${link[0]}" class="ac-guide-link">${link[1]} <span>›</span></a></section>`).join('')}`;}
    if(part==='about'){title=sub==='confidentiality'?'Confidentiality Agreement':sub==='risk'?'Risk Disclosure Agreement':'About us';if(documents[sub]){back='#/account/about';body=`<article class="ac-card ac-document">${documents[sub].map(p=>`<p>${p}</p>`).join('')}</article>`;}else body=banner('about','Color Win','Your account. Your experience.')+`<div class="ac-about-links">${row('#/account/about/confidentiality','Confidentiality Agreement','about-us')}${row('#/account/about/risk','Risk Disclosure Agreement','key')}</div>`;}
    if(part==='settings'){title='Settings Center';body=settings();if(sub){back='#/account/settings';if(sub==='nickname'){title='Change nickname';body=`<form id="ac-nickname" class="ac-form">${field('nickname','Nickname','text','Enter nickname','minlength="2" maxlength="30" value="'+esc(nickname())+'"')}${primary('Save changes')}</form>`;}if(sub==='password'){title='Change login password';body=`<form id="ac-password" class="ac-form">${field('old','Login password','password','Login password','autocomplete="current-password"')}${field('password','New login password','password','New login password','minlength="8" maxlength="72" autocomplete="new-password"')}${field('confirm','Confirm new password','password','Confirm new password','minlength="8" maxlength="72" autocomplete="new-password"')}<a class="ac-forgot" href="#/account/settings/recovery">Forgot Old login password</a>${primary('Save changes')}</form>`;}if(sub==='email'){title='Bind mailbox';body=`<form id="ac-email" class="ac-form">${field('email','Mail','email','Please input your email','autocomplete="email"')}<label class="ac-field"><span>${icon('check')}Verification Code</span><div class="ac-input"><input name="token" inputmode="numeric" aria-label="Verification code" placeholder="Enter confirmation code" maxlength="8" pattern="[0-9]{6,8}"><button type="button" id="ac-email-send">Send</button></div></label><p class="ac-status" id="ac-email-status" role="status"></p>${primary('Bind')}</form>`;}if(sub==='recovery'){title='Password recovery';body='<section class="ac-card"><h2>Recover your account</h2><p>Use the password recovery option on the login page. If your account has no verified email, contact account support to recover access.</p><a class="ac-guide-link" href="#/login">Open login ›</a></section>';}}}
    return `<section class="account-subpage" data-account-route="${route}">${header(title,back)}<main class="ac-content">${body}</main></section>`;
  }
  async function bind(route,toast){const page=document.querySelector('.account-subpage');let tab=route.endsWith('/information')?'information':route.includes('/coupons')?'unused':route.includes('/statistics')?'today':'notification';let stats=[];
    if(route==='#/account/transactions'){window.ColorWinTransactions.bind();return;}
    const paint=()=>{if(!page.isConnected)return;const list=page.querySelector('#ac-list');if(route.includes('/notifications')){list.innerHTML=tab==='information'?(window.ColorWinOperations?.config?.announcements?.length?window.ColorWinOperations.config.announcements.map(n=>[n.title,n.message]):notices).map(([t,p])=>`<article class="ac-card ac-notification"><h2>${icon('announcement')}${esc(t)}</h2><p>${esc(p)}</p></article>`).join('')+'<p class="ac-end">No more</p>':data.notifications.length?data.notifications.map(n=>`<article class="ac-card ac-notification"><h2>${icon(n.kind==='withdrawal'?'withdraw':n.kind==='deposit'?'deposit-history':'message')}${esc(n.title)}</h2><p>${esc(n.message)}</p><time>${date(n.created_at)}</time></article>`).join('')+'<p class="ac-end">No more</p>':empty();}
      if(route.includes('/gifts'))list.innerHTML=data.gifts.length?data.gifts.map(g=>`<div class="ac-gift-history"><div><strong>Successfully received${g.kind==='coupon'?' · Coupon':''}</strong><time>${date(g.created_at)}</time></div><b>${money(g.amount)}</b></div>`).join('')+'<p class="ac-end">No more</p>':empty();
      if(route.includes('/coupons')){const coupons=data.gifts.filter(g=>g.kind==='coupon'&&(g.used_at?'used':new Date(g.expires_at)<=new Date()?'expired':'unused')===tab);list.innerHTML=coupons.length?coupons.map(g=>`<article class="ac-card ac-coupon"><strong>${money(g.amount)}</strong><div><h2>Top-Up Coupon</h2><p>Minimum deposit ${money(g.minimum_deposit)}</p><small>Expires ${date(g.expires_at)}</small></div></article>`).join(''):empty();}
      if(route.includes('/statistics')){const categories=[['lottery','Lottery'],['video','Video'],['slot','Slot'],['fish','Fish'],['sport','Sport'],['chess','Chess & Card']];page.querySelector('#ac-stats').innerHTML=`<section class="ac-card ac-total"><strong>${money(stats.reduce((n,g)=>n+Number(g.bet),0))}</strong><span>Total bet</span></section><section class="ac-card ac-categories">${categories.map(([id,label])=>{const g=stats.find(g=>g.category===id)||{};return `<article><h2>${icon('statistics')}${label}</h2><dl><div><dt>Total bet</dt><dd>${money(g.bet)}</dd></div><div><dt>Number of bets</dt><dd>${g.count||0}</dd></div><div><dt>Winning amount</dt><dd class="ac-win">${money(g.winnings)}</dd></div></dl></article>`;}).join('')}</section>`;}
      page.querySelectorAll('[data-ac-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.acTab===tab)));
    };
    const statLoad=async()=>{if(preview()){stats=[];paint();return;}const period=tab;const result=await window.ColorWinAuth.accountRpc('colorwin_game_statistics',{p_period:period});if(tab===period){stats=result;paint();}};
    page.querySelectorAll('[data-ac-tab]').forEach(b=>b.onclick=async()=>{tab=b.dataset.acTab;paint();if(route.includes('/statistics'))try{await statLoad();}catch{toast('Statistics could not be loaded. Please retry.',true);}});
    if(page.querySelector('#ac-list')||page.querySelector('#ac-stats'))paint();
    const submit=(id,handler)=>{const form=page.querySelector(id);if(!form)return;form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type="submit"]');b.disabled=true;try{await handler(form);}catch(err){toast(err.message||'Please try again.',true);}finally{b.disabled=false;}};};
    submit('#ac-gift',async form=>{const code=form.elements.code.value.trim().toUpperCase();if(!/^[A-F0-9]{32}$/.test(code))throw Error('Invalid gift code.');if(preview())throw Error('Gift redemption requires your signed-in account.');await window.ColorWinAuth.accountRpc('colorwin_redeem_gift',{p_code:code});await load();paint();form.reset();toast('Successfully redeemed');});
    submit('#ac-feedback',async form=>{if(preview())throw Error('Sign in to send feedback to the team.');await window.ColorWinAuth.accountRpc('colorwin_submit_feedback',{p_message:form.elements.message.value.trim()});form.reset();toast('Feedback sent to the team');});
    submit('#ac-nickname',async form=>{const n=form.elements.nickname.value.trim();if(n.length<2)throw Error('Enter a nickname of 2–30 characters.');if(preview())localStorage.setItem('cw_preview_nickname',n);else await window.ColorWinAuth.setNickname(n);toast('Nickname updated');location.hash='#/account/settings';});
    page.querySelectorAll('[data-ac-eye]').forEach(b=>b.onclick=()=>{const input=page.querySelector(`[name="${b.dataset.acEye}"]`);input.type=input.type==='password'?'text':'password';b.innerHTML=eye(input.type==='text');b.setAttribute('aria-pressed',String(input.type==='text'));b.setAttribute('aria-label',(input.type==='password'?'Show ':'Hide ')+input.placeholder.toLowerCase());});
    submit('#ac-password',async form=>{if(form.elements.password.value!==form.elements.confirm.value)throw Error('New passwords do not match.');if(form.elements.old.value===form.elements.password.value)throw Error('Choose a different new password.');if(preview())throw Error('Sign in to change your login password.');await window.ColorWinAuth.changePassword(form.elements.old.value,form.elements.password.value);form.reset();toast('Password updated');location.hash='#/account/settings';});
    const emailForm=page.querySelector('#ac-email');let sentEmail='';if(emailForm){const send=page.querySelector('#ac-email-send');send.onclick=async()=>{if(!emailForm.elements.email.reportValidity())return;send.disabled=true;try{if(preview())throw Error('Sign in to verify your mailbox.');sentEmail=emailForm.elements.email.value.trim();await window.ColorWinAuth.sendEmailChange(sentEmail);page.querySelector('#ac-email-status').textContent='Check your confirmation email. Enter its code, or confirm the email link and then tap Bind.';toast('Confirmation email sent');}catch(e){sentEmail='';toast(e.message,true);}finally{send.disabled=false;}};emailForm.elements.email.oninput=()=>{sentEmail='';};submit('#ac-email',async form=>{if(!sentEmail||sentEmail!==form.elements.email.value.trim())throw Error('Send a verification code to this email first.');const token=form.elements.token.value.trim();const result=token?await window.ColorWinAuth.confirmEmailChange(sentEmail,token):await window.ColorWinAuth.refreshUser();if(result?.email!==sentEmail){page.querySelector('#ac-email-status').textContent='Confirm the email links or enter the verification code, then tap Bind again.';return;}toast('Mailbox verified');location.hash='#/account/settings';});}
    const avatar=page.querySelector('#ac-avatar');if(avatar)avatar.onclick=()=>{sessionStorage.setItem('cw_avatar_return','#/account/settings');location.hash='#/account/avatar';};
    const copy=page.querySelector('#ac-copy');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(String(window.ColorWinAuth.profile?.public_uid||''));toast('UID copied');}catch{toast('Clipboard unavailable.',true);}};
    const version=page.querySelector('#ac-version');if(version)version.onclick=()=>toast('Version is up to date');
    if(page.querySelector('#ac-list')||page.querySelector('#ac-stats'))try{await load();if(route.includes('/statistics'))await statLoad();paint();}catch{toast('Account records could not be loaded. Please retry.',true);}
  }
  async function refreshBalance(){const requested=user();await load();if(user()!==requested)return;document.querySelectorAll('.balance-value,.wallet-overview>strong,.wallet-rings>div:first-child>b,.home-balance-value,[data-tn-wallet-value]').forEach(e=>e.textContent=money(balance()));document.querySelectorAll('.wallet-balance strong').forEach(e=>{if(e.firstChild?.nodeType===Node.TEXT_NODE)e.firstChild.textContent=money(balance())+' ';});}
  const accountSubroutes=new Set([
    '#/account/settings/nickname','#/account/settings/password','#/account/settings/email','#/account/settings/recovery',
    '#/account/about/confidentiality','#/account/about/risk'
  ]);
  window.ColorWinAccount={routes,matches:r=>Object.values(routes).some(v=>r===v&&v.startsWith("#/account/"))||accountSubroutes.has(r),view,bind,load,balance,nickname,refreshBalance};
})();


